function findExpirySuggestion(plan, dates) {
  for (const day of DAYS) {
    const meal = MEALS[plan[day]];
    if (!meal) continue;
    for (const [name] of meal.ingredients) {
      const plannedDate = new Date(`2026-09-${8 + DAYS.indexOf(day)}T12:00:00`);
      const useBy = dates[name] ? new Date(`${dates[name]}T12:00:00`) : null;
      if (useBy && useBy < plannedDate) {
        return {
          name,
          meal: plan[day],
          from: day,
          to: DAYS[Math.max(0, useBy.getDate() - 8)] || "Monday",
          date: dates[name],
        };
      }
    }
  }
  return null;
}

function ThisWeek({ plan, outcomes, finishDay, suggestion, setCurrent }) {
  const [today] = useState("Monday");
  const tonight = plan[today];
  const tonightDone = outcomes[today];
  return (
    <>
      <Header
        overline="TODAY"
        title={tonightDone ? "Your next shop" : "What do you need to do now?"}
        sub={tonightDone ? "Plan the next week when you are ready." : `Did you cook ${tonight} tonight?`}
      />
      {suggestion && (
        <View style={s.alert}>
          <View style={s.alertIcon}>
            <Ionicons name="time-outline" size={20} color={C.amber} />
          </View>
          <View style={{ flex: 1 }}>
            <Text style={s.alertTitle}>Use-by date suggestion</Text>
            <Text style={s.alertText}>
              {suggestion.name} is dated {niceDate(suggestion.date)}. Move{" "}
              {suggestion.meal} from {suggestion.from} to {suggestion.to}?
            </Text>
            <TouchableOpacity
              onPress={() => {
                const a = plan[suggestion.from],
                  b = plan[suggestion.to];
                setCurrent((p) => ({
                  ...p,
                  [suggestion.from]: b,
                  [suggestion.to]: a,
                }));
              }}
            >
              <Text style={s.link}>Move meal automatically</Text>
            </TouchableOpacity>
          </View>
        </View>
      )}
      <View style={[s.weekCard, { padding: 20 }]}>
        <Text style={s.sectionLabel}>TONIGHT</Text>
        <Text style={[s.mealName, { fontSize: 24 }]}>{tonight}</Text>
        <Text style={s.mealMeta}>
          {MEALS[tonight]?.time || 30} minutes
        </Text>
        {!tonightDone ? (
          <View style={s.outcomeRow}>
            <SmallButton icon="checkmark" text="Cooked" onPress={() => finishDay(today, "Cooked")} />
            <SmallButton icon="restaurant-outline" text="Ate out" onPress={() => finishDay(today, "Ate out")} pale />
            <SmallButton icon="bag-handle-outline" text="Takeaway" onPress={() => finishDay(today, "Takeaway")} pale />
          </View>
        ) : (
          <View style={s.status}>
            <Ionicons name="checkmark-circle" size={17} color={C.green} />
            <Text style={s.statusText}>{tonightDone}</Text>
          </View>
        )}
      </View>
    </>
  );
}

