function GuidedPlanner({
  flow,
  setFlow,
  plan,
  daySlots,
  setDaySlots,
  setDinner,
  household,
  open,
  basket,
  addNonFood,
  quickMealChoices,
  rememberMealChoice,
  customRecipes,
  saveRecipe,
  initialDayIndex = 0,
  dinnerAssignments = {},
}) {
  const [dayIndex, setDayIndex] = useState(initialDayIndex);
  const [screen, setScreen] = useState("day");
  const [slot, setSlot] = useState("Breakfast");
  const [pendingChoice, setPendingChoice] = useState("");
  const [people, setPeople] = useState([]);
  const [extra, setExtra] = useState("");
  const [typedChoice, setTypedChoice] = useState("");
  const [ingredientText, setIngredientText] = useState("");
  const [ingredients, setIngredients] = useState([]);
  const [expandedReviewDay, setExpandedReviewDay] = useState(null);
  const [assignmentNotice, setAssignmentNotice] = useState("");
  const day = DAYS[dayIndex];
  const slots = daySlots[day] || {};
  const slotItems = (name) => {
    const saved = slots[name];
    return Array.isArray(saved) ? saved : saved ? [saved] : [];
  };
  const dinnerItems = dinnerAssignments[day] || (plan[day] ? [{ meal: plan[day], memberIds: [] }] : []);
  const peopleFor = (memberIds) =>
    (memberIds || [])
      .map(
        (id) =>
          household.members
            .find((member) => member.id === id)
            ?.name.split(" ")[0],
      )
      .filter(Boolean)
      .join(" & ");
  const itemSummary = (items, mealKey = "name") =>
    items
      .map((item) => `${peopleFor(item.memberIds) || "No one"} — ${item[mealKey]}`)
      .join("\n");
  const reviewCompleteDays = DAYS.filter(
    (name) => Boolean(dinnerAssignments[name]?.length || plan[name]),
  ).length;
  const starterOptions = ["No meal needed"];
  const options = [
    ...new Set([
      ...(slot === "Dinner" ? Object.keys(customRecipes || {}) : []),
      ...(quickMealChoices?.[slot] || []),
      ...starterOptions,
    ]),
  ];
  const selected = slot === "Dinner" ? plan[day] : slots[slot]?.name;
  const allIds = household.members.map((member) => member.id);
  const saveSelection = (name, memberIds) => {
    const previousItems = slot === "Dinner" ? dinnerItems : slotItems(slot);
    const replaced = previousItems.find(
      (item) =>
        item[slot === "Dinner" ? "meal" : "name"] !== name &&
        (item.memberIds || []).some((id) => memberIds.includes(id)),
    );
    if (replaced) {
      const changedNames = memberIds.map((id) => household.members.find((member) => member.id === id)?.name.split(" ")[0]).filter(Boolean).join(" & ");
      setAssignmentNotice(`${changedNames} will now have ${name} instead of ${replaced[slot === "Dinner" ? "meal" : "name"]}.`);
    } else setAssignmentNotice("");
    if (slot === "Dinner") return setDinner(day, name, memberIds);
    setDaySlots((current) => ({
      ...current,
      [day]: {
        ...(current[day] || {}),
        [slot]: [
          ...((Array.isArray(current[day]?.[slot])
            ? current[day][slot]
            : current[day]?.[slot]
              ? [current[day][slot]]
              : [])
            .map((item) => ({
              ...item,
              memberIds: (item.memberIds || []).filter(
                (id) => !memberIds.includes(id),
              ),
            }))
            .filter((item) => item.memberIds.length)),
          { name, memberIds },
        ],
      },
    }));
  };
  const chooseSlot = (nextSlot) => {
    setSlot(nextSlot);
    setPendingChoice("");
    setScreen("choices");
  };
  const chooseFood = (name) => {
    if (name === "No meal needed") {
      setPendingChoice(name);
      setPeople([]);
      setScreen("audience");
      return;
    }
    const knownQuickPick = (quickMealChoices?.[slot] || []).includes(name);
    if (!MEALS[name] && !customRecipes?.[name] && !knownQuickPick) {
      setPendingChoice(name);
      setScreen("kind");
      return;
    }
    rememberMealChoice(slot, name);
    setPendingChoice(name);
    setPeople([]);
    setScreen("audience");
  };
  const startIngredients = () => {
    setPeople([]);
    setIngredients([]);
    setIngredientText("");
    setScreen("ingredients");
  };
  const savePrePacked = () => {
    if (slot === "Dinner")
      saveRecipe(pendingChoice, [[pendingChoice, 1, "pack", null, false]]);
    rememberMealChoice(slot, pendingChoice);
    setPeople([]);
    setScreen("audience");
  };
  const saveAndReturn = (memberIds) => {
    saveSelection(pendingChoice, memberIds);
    setExpandedReviewDay(null);
    setFlow("review");
  };
  const completeDay = () => {
    if (dayIndex === DAYS.length - 1) setFlow("extras");
    else {
      setDayIndex((index) => index + 1);
      setSlot("Breakfast");
      setScreen("day");
    }
  };
  if (flow === "intro")
    return (
      <>
        <Header
          overline="YOUR FIRST WEEK"
          title="Tell us your usual meals"
          sub="There are no preset choices. Start by typing what your household actually eats."
        />
        <View style={s.info}>
          <Ionicons name="sparkles-outline" size={20} color={C.green} />
          <Text style={s.infoText}>
            For the first few shops, you will type meals and products in. We
            remember them safely. Each week after that, your personal quick
            picks grow — making planning faster and less stressful.
          </Text>
        </View>
        <View style={s.quickActionArea}>
          <View style={s.bigDecision}>
            <Ionicons name="restaurant-outline" size={28} color={C.white} />
            <Text style={s.bigDecisionText}>You type it once</Text>
            <Text style={s.bigDecisionSub}>
              We learn your meals, products and household routine.
            </Text>
          </View>
        </View>
        <Button
          text="Start with Monday"
          icon="arrow-forward"
          onPress={() => setFlow("guided")}
        />
      </>
    );
  if (screen === "kind")
    return (
      <>
        <Header
          overline="ONE QUICK QUESTION"
          title={`What is ${pendingChoice}?`}
          sub="This lets us build an accurate basket."
        />
        <View style={s.quickActionArea}>
          <TouchableOpacity style={s.bigDecision} onPress={savePrePacked}>
            <Ionicons name="cube-outline" size={29} color={C.white} />
            <Text style={s.bigDecisionText}>Pre-packed item</Text>
            <Text style={s.bigDecisionSub}>
              Buy it as one product — such as cereal, microwave rice or a ready
              meal.
            </Text>
          </TouchableOpacity>
          <TouchableOpacity
            style={[s.bigDecision, s.bigDecisionPale]}
            onPress={startIngredients}
          >
            <Ionicons name="restaurant-outline" size={29} color={C.green} />
            <Text style={[s.bigDecisionText, { color: C.green }]}>
              Made from ingredients
            </Text>
            <Text style={[s.bigDecisionSub, { color: C.muted }]}>
              Tell us what normally goes in it — such as burritos or curry.
            </Text>
          </TouchableOpacity>
        </View>
        <TouchableOpacity
          onPress={() => setScreen("choices")}
          style={s.setupBack}
        >
          <Text style={s.notNow}>Type something else</Text>
        </TouchableOpacity>
      </>
    );
  if (screen === "ingredients")
    return (
      <>
        <Header
          overline="SAVE A FAMILY MEAL"
          title={`What goes in ${pendingChoice}?`}
          sub="Add the ingredients you normally use. We will use this recipe for your basket from now on."
        />
        <View style={s.addBar}>
          <Ionicons name="add" size={20} color={C.green} />
          <TextInput
            value={ingredientText}
            onChangeText={setIngredientText}
            onSubmitEditing={() => {
              const value = ingredientText.trim();
              if (value) {
                setIngredients((current) => [...current, value]);
                setIngredientText("");
              }
            }}
            placeholder="e.g. chicken breast"
            placeholderTextColor={C.muted}
            style={s.input}
          />
          <TouchableOpacity
            onPress={() => {
              const value = ingredientText.trim();
              if (value) {
                setIngredients((current) => [...current, value]);
                setIngredientText("");
              }
            }}
          >
            <Text style={s.link}>Add</Text>
          </TouchableOpacity>
        </View>
        <View style={s.card}>
          {ingredients.length ? (
            ingredients.map((item, index) => (
              <View key={item + index} style={s.itemRow}>
                <View style={s.iconBox}>
                  <Ionicons name="basket-outline" size={18} color={C.green} />
                </View>
                <Text style={[s.rowTitle, { flex: 1 }]}>{item}</Text>
                <TouchableOpacity
                  onPress={() =>
                    setIngredients((current) =>
                      current.filter((_, i) => i !== index),
                    )
                  }
                >
                  <Ionicons
                    name="close-circle-outline"
                    size={20}
                    color={C.muted}
                  />
                </TouchableOpacity>
              </View>
            ))
          ) : (
            <View style={s.itemRow}>
              <Text style={s.rowDetail}>
                Add each item one at a time — for example wraps, chicken, rice
                and salsa.
              </Text>
            </View>
          )}
        </View>
        <Button
          text={
            ingredients.length
              ? `Save ${pendingChoice}`
              : "Add ingredients to continue"
          }
          icon="checkmark"
          disabled={!ingredients.length}
          onPress={() => {
            const recipeIngredients = ingredients.map((name) => [
              name,
              1,
              "pack",
              null,
              false,
            ]);
            saveRecipe(pendingChoice, recipeIngredients);
            rememberMealChoice(slot, pendingChoice);
            setPeople([]);
            setScreen("audience");
          }}
        />
        <TouchableOpacity
          onPress={() => setScreen("choices")}
          style={s.setupBack}
        >
          <Text style={s.notNow}>Back to choice</Text>
        </TouchableOpacity>
      </>
    );
  if (flow === "extras")
    return (
      <>
        <Header
          overline="STEP 2 OF 4"
          title="Anything else this week?"
          sub="Add food, drinks or household items."
        />
        <View style={s.addBar}>
          <Ionicons name="add" size={20} color={C.green} />
          <TextInput
            value={extra}
            onChangeText={setExtra}
            placeholder="Coke, toothpaste, toilet roll…"
            placeholderTextColor={C.muted}
            style={s.input}
          />
          <TouchableOpacity
            onPress={() => {
              if (extra.trim()) {
                addNonFood(extra.trim());
                setExtra("");
              }
            }}
          >
            <Text style={s.link}>Add</Text>
          </TouchableOpacity>
        </View>
        <Button
          text={`Review ${basket.length} basket items`}
          icon="arrow-forward"
          onPress={() => setFlow("review")}
        />
      </>
    );
  if (flow === "review")
    return (
      <>
        <Header
          overline="STEP 3 OF 4"
          title="Review your meals"
          sub="Open a day only if you want to change it."
        />
        <View style={s.progress}>
          <View style={s.progressTop}>
              <Text style={s.progressTitle}>Your plan so far</Text>
              <Text style={s.progressCount}>{reviewCompleteDays} of 7 days complete</Text>
          </View>
          <View style={s.track}>
            <View style={[s.trackFill, { width: `${(reviewCompleteDays / 7) * 100}%` }]} />
          </View>
        </View>
        <View style={s.weekCard}>
          {DAYS.map((name, index) => (
            <TouchableOpacity
              key={name}
              style={s.planRow}
              onPress={() =>
                setExpandedReviewDay((current) =>
                  current === name ? null : name,
                )
              }
            >
              <View style={{ flex: 1 }}>
                <Text style={s.dayName}>{name}</Text>
                {(() => {
                  const breakfast = Array.isArray(daySlots[name]?.Breakfast)
                    ? daySlots[name].Breakfast
                    : daySlots[name]?.Breakfast ? [daySlots[name].Breakfast] : [];
                  const lunch = Array.isArray(daySlots[name]?.Lunch)
                    ? daySlots[name].Lunch
                    : daySlots[name]?.Lunch ? [daySlots[name].Lunch] : [];
                  const dinner = dinnerAssignments[name] || (plan[name] ? [{ meal: plan[name], memberIds: [] }] : []);
                  return <>
                    <Text style={[s.mealName, !dinner.length && { color: C.muted }]}>
                      {dinner.length ? itemSummary(dinner, "meal") : `${name} — still to plan`}
                    </Text>
                    {expandedReviewDay === name && <View style={{ marginTop: 10 }}>
                      <TouchableOpacity onPress={() => { setDayIndex(index); setSlot("Dinner"); setFlow("guided"); setScreen("choices"); }}>
                        <Text style={s.link}>Change {name}'s dinner</Text>
                      </TouchableOpacity>
                    </View>}
                  </>;
                })()}
              </View>
              <Ionicons name={expandedReviewDay === name ? "chevron-up" : "chevron-down"} size={19} color={C.muted} />
            </TouchableOpacity>
          ))}
        </View>
        <Button
          text="Compare supermarkets"
          icon="arrow-forward"
          disabled={!reviewCompleteDays}
          onPress={() => open("Compare")}
        />
      </>
    );
  const completed = Boolean(
    slotItems("Breakfast").length &&
      slotItems("Lunch").length &&
      dinnerItems.length,
  );
  if (screen === "choices")
    return (
      <>
        <Header
          overline={`${day.toUpperCase()} · ${slot.toUpperCase()}`}
          title={`Choose ${slot.toLowerCase()}`}
          sub="Start by typing what you want. We will remember it as a quick pick next time."
        />
        <View style={s.addBar}>
          <Ionicons name="create-outline" size={20} color={C.green} />
          <TextInput
            value={typedChoice}
            onChangeText={setTypedChoice}
            onSubmitEditing={() => {
              const value = typedChoice.trim();
              if (value) {
                setTypedChoice("");
                chooseFood(value);
              }
            }}
            placeholder={`Type a ${slot.toLowerCase()}…`}
            placeholderTextColor={C.muted}
            style={s.input}
          />
          <TouchableOpacity
            onPress={() => {
              const value = typedChoice.trim();
              if (value) {
                setTypedChoice("");
                chooseFood(value);
              }
            }}
          >
            <Text style={s.link}>Next</Text>
          </TouchableOpacity>
        </View>
        {(quickMealChoices?.[slot] || []).length > 0 && (
          <Text style={s.sectionLabel}>YOUR QUICK PICKS</Text>
        )}
        <View style={s.quickChoiceStack}>
          {options.map((name) => (
            <TouchableOpacity
              key={name}
              onPress={() => chooseFood(name)}
              style={s.quickChoice}
            >
              <View style={s.iconBox}>
                <Ionicons
                  name={
                    slot === "Dinner"
                      ? "restaurant-outline"
                      : slot === "Breakfast"
                        ? "sunny-outline"
                        : "briefcase-outline"
                  }
                  size={22}
                  color={C.green}
                />
              </View>
              <View style={{ flex: 1 }}>
                <Text style={s.quickChoiceTitle}>{name}</Text>
                <Text style={s.rowDetail}>
                  {slot === "Dinner" && MEALS[name]
                    ? `${MEALS[name].time} minutes · saved family meal`
                    : "Tap to continue"}
                </Text>
              </View>
              <Ionicons name="chevron-forward" size={22} color={C.muted} />
            </TouchableOpacity>
          ))}
        </View>
        <TouchableOpacity onPress={() => setScreen("day")} style={s.setupBack}>
          <Text style={s.notNow}>Back to Monday</Text>
        </TouchableOpacity>
      </>
    );
  if (screen === "audience")
    return (
      <>
        <Header
          overline={`${day.toUpperCase()} · ${slot.toUpperCase()}`}
          title="Who is this for?"
          sub={pendingChoice}
        />
        <View style={s.card}>
          {household.members.map((member) => {
            const on = people.includes(member.id);
            return <TouchableOpacity key={member.id} onPress={() => setPeople((current) => on ? current.filter((id) => id !== member.id) : [...current, member.id])} style={s.quickPerson}>
              <View style={s.avatar}><Text style={s.avatarText}>{member.name[0]}</Text></View>
              <Text style={[s.rowTitle, { flex: 1 }]}>{member.name.split(" ")[0]}</Text>
              <Ionicons name={on ? "checkbox" : "square-outline"} size={25} color={C.green} />
            </TouchableOpacity>;
          })}
        </View>
        <TouchableOpacity
          onPress={() => setPeople(allIds)}
          style={s.setupBack}
        >
          <Text style={s.link}>Select everyone</Text>
        </TouchableOpacity>
        <Button text={`Save for ${people.length || "no one"}`} icon="checkmark" disabled={!people.length} onPress={() => saveAndReturn(people)} />
      </>
    );
  if (screen === "people")
    return (
      <>
        <Header
          overline={`${day.toUpperCase()} · ${slot.toUpperCase()}`}
          title="Select who is eating"
          sub="Only the selected people are included in quantities."
        />
        <View style={s.card}>
          {household.members.map((member) => {
            const on = people.includes(member.id);
            return (
              <TouchableOpacity
                key={member.id}
                onPress={() =>
                  setPeople((current) =>
                    on
                      ? current.filter((id) => id !== member.id)
                      : [...current, member.id],
                  )
                }
                style={s.quickPerson}
              >
                <View style={s.avatar}>
                  <Text style={s.avatarText}>{member.name[0]}</Text>
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={s.rowTitle}>{member.name}</Text>
                  <Text style={s.rowDetail}>{member.role}</Text>
                </View>
                <Ionicons
                  name={on ? "checkbox" : "square-outline"}
                  size={25}
                  color={C.green}
                />
              </TouchableOpacity>
            );
          })}
        </View>
        <Button
          text={`Save for ${people.length || "no one"}`}
          icon="checkmark"
          disabled={!people.length}
          onPress={() => saveAndReturn(people)}
        />
      </>
    );
  return (
    <>
      <Header
        overline={`PLAN DAY ${dayIndex + 1} OF 7`}
        title={day}
        sub={completed ? `${day} is ready` : `${day} needs ${!slotItems("Breakfast").length ? "breakfast" : !slotItems("Lunch").length ? "lunch" : "dinner"}`}
      />
      {!!assignmentNotice && (
        <View style={s.confirm}>
          <Ionicons name="checkmark-circle" size={18} color={C.green} />
          <Text style={s.confirmTitle}>{assignmentNotice}</Text>
        </View>
      )}
      <View style={s.quickActionArea}>
        {["Breakfast", "Lunch", "Dinner"].map((name) => {
          const items = name === "Dinner" ? dinnerItems : slotItems(name);
          const choice =
            name === "Dinner" ? itemSummary(items, "meal") : itemSummary(items);
          return (
            <TouchableOpacity
              key={name}
              onPress={() => chooseSlot(name)}
              style={[s.dayDecision, choice && s.dayDecisionDone]}
            >
              <Ionicons
                name={
                  name === "Breakfast"
                    ? "sunny-outline"
                    : name === "Lunch"
                      ? "briefcase-outline"
                      : "restaurant-outline"
                }
                size={26}
                color={choice ? C.white : C.green}
              />
              <View style={{ flex: 1 }}>
                <Text style={[s.dayDecisionText, choice && { color: C.white }]}>
                  {name}
                </Text>
                <Text style={[s.dayDecisionSub, choice && { color: C.white }]}>
                  {choice || "Not planned"}
                </Text>
              </View>
              <Ionicons
                name={choice ? "checkmark-circle" : "chevron-forward"}
                size={24}
                color={choice ? C.white : C.green}
              />
            </TouchableOpacity>
          );
        })}
      </View>
      <Button
        text={
          completed
            ? dayIndex === 6
              ? "Finish week and review"
              : `Complete ${day} →`
            : "Choose breakfast, lunch and dinner"
        }
        icon="arrow-forward"
        disabled={!completed}
        onPress={completeDay}
      />
    </>
  );
}

function WeeklyConsumables({
  category,
  items,
  savedChoices,
  rememberChoice,
  open,
}) {
  const [custom, setCustom] = useState("");
  const [milkType, setMilkType] = useState("Semi-skimmed");
  const [milkSize, setMilkSize] = useState("2 pints");
  const choices = [...new Set([...WEEKLY_CHOICES[category], ...savedChoices])];
  const addCustom = () => {
    const name =
      custom.trim() ||
      (category === "Drinks" ? `Milk · ${milkType} · ${milkSize}` : "");
    if (!name) return;
    rememberChoice(category, name);
    open({ category, name, items });
    setCustom("");
  };
  return (
    <>
      <Header
        overline={`PLAN ${category.toUpperCase()}`}
        title={`${category} for this week`}
        sub="Choose an item, then select exactly who will be consuming it."
      />
      <View style={s.setupPanel}>
        <TextInput
          value={custom}
          onChangeText={setCustom}
          placeholder={`Type a ${category.toLowerCase().slice(0, -1)}…`}
          placeholderTextColor={C.muted}
          style={s.setupInput}
        />
        {category === "Drinks" && (
          <>
            <Text style={s.sectionLabel}>IF YOU ARE ADDING MILK</Text>
            <View style={s.choiceRow}>
              {["Whole", "Semi-skimmed", "Skimmed", "Oat"].map((type) => (
                <TouchableOpacity
                  key={type}
                  onPress={() => setMilkType(type)}
                  style={[s.choiceChip, milkType === type && s.choiceChipOn]}
                >
                  <Text
                    style={[s.choiceText, milkType === type && s.choiceTextOn]}
                  >
                    {type}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>
            <View style={s.choiceRow}>
              {["1 pint", "2 pints", "4 pints"].map((size) => (
                <TouchableOpacity
                  key={size}
                  onPress={() => setMilkSize(size)}
                  style={[s.choiceChip, milkSize === size && s.choiceChipOn]}
                >
                  <Text
                    style={[s.choiceText, milkSize === size && s.choiceTextOn]}
                  >
                    {size}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>
          </>
        )}
        <Button
          text={
            custom.trim()
              ? "Add this item"
              : category === "Drinks"
                ? "Add selected milk"
                : "Type an item to add"
          }
          pale
          disabled={!custom.trim() && category !== "Drinks"}
          icon="add"
          onPress={addCustom}
        />
      </View>
      {(savedChoices || []).length > 0 && (
        <Text style={s.sectionLabel}>YOUR SAVED QUICK PICKS</Text>
      )}
      <View style={s.card}>
        {choices.map((name) => {
          const item = items.find((entry) => entry.name === name);
          return (
            <TouchableOpacity
              key={name}
              onPress={() => open({ category, name, items })}
              style={[s.itemRow, item && s.mealChoiceOn]}
            >
              <View style={s.iconBox}>
                <Ionicons
                  name={
                    category === "Drinks" ? "cafe-outline" : "nutrition-outline"
                  }
                  size={18}
                  color={C.green}
                />
              </View>
              <View style={{ flex: 1 }}>
                <Text style={s.rowTitle}>{name}</Text>
                <Text style={s.rowDetail}>
                  {item
                    ? item.memberIds.length +
                      " family member" +
                      (item.memberIds.length === 1 ? "" : "s") +
                      " selected"
                    : "Choose who will have this"}
                </Text>
              </View>
              <Ionicons
                name={item ? "checkmark-circle" : "add-circle-outline"}
                size={21}
                color={C.green}
              />
            </TouchableOpacity>
          );
        })}
      </View>
    </>
  );
}

