function RecipeLibrary({ recipes = {}, setRecipes, back }) {
  const blank = { name: "", servings: "4", time: "30", method: "", ingredients: [] };
  const [draft, setDraft] = useState(blank);
  const [editing, setEditing] = useState("");
  const [ingredient, setIngredient] = useState({ name: "", qty: "1", unit: "pack" });
  const addIngredient = () => {
    if (!ingredient.name.trim()) return;
    setDraft((current) => ({ ...current, ingredients: [...current.ingredients, [ingredient.name.trim(), Number(ingredient.qty) || 1, ingredient.unit.trim() || "pack", null, false]] }));
    setIngredient({ name: "", qty: "1", unit: "pack" });
  };
  const edit = (name, recipe) => {
    setEditing(name);
    setDraft({ name, servings: String(recipe.servings || 4), time: String(recipe.time || 30), method: recipe.method || "", ingredients: recipe.ingredients || [] });
  };
  const save = () => {
    const name = draft.name.trim();
    if (!name || !draft.ingredients.length) return;
    setRecipes((current) => {
      const next = { ...current };
      if (editing && editing !== name) delete next[editing];
      next[name] = { servings: Number(draft.servings) || 4, time: Number(draft.time) || 30, method: draft.method.trim(), ingredients: draft.ingredients };
      return next;
    });
    setDraft(blank);
    setEditing("");
  };
  return <>
    <Back onPress={back} />
    <Header overline="MY ACCOUNT" title="My recipes" sub="Meals saved for planning and shopping." />
    {!!Object.keys(recipes).length && <View style={s.card}>{Object.entries(recipes).map(([name, recipe]) => <TouchableOpacity key={name} style={s.itemRow} onPress={() => edit(name, recipe)}><View style={s.iconBox}><Ionicons name="restaurant-outline" size={19} color={C.green} /></View><View style={{ flex: 1 }}><Text style={s.rowTitle}>{name}</Text><Text style={s.rowDetail}>{recipe.ingredients?.length || 0} ingredients · {recipe.time || 30} minutes</Text></View><Ionicons name="create-outline" size={18} color={C.muted} /></TouchableOpacity>)}</View>}
    <Text style={s.sectionLabel}>{editing ? "EDIT RECIPE" : "ADD A RECIPE"}</Text>
    <TextInput value={draft.name} onChangeText={(name) => setDraft((current) => ({ ...current, name }))} placeholder="Recipe name" placeholderTextColor={C.muted} style={s.setupInput} />
    <View style={s.optionRow}><TextInput value={draft.servings} onChangeText={(servings) => setDraft((current) => ({ ...current, servings }))} placeholder="Servings" keyboardType="number-pad" placeholderTextColor={C.muted} style={[s.setupInput, { flex: 1 }]} /><TextInput value={draft.time} onChangeText={(time) => setDraft((current) => ({ ...current, time }))} placeholder="Minutes" keyboardType="number-pad" placeholderTextColor={C.muted} style={[s.setupInput, { flex: 1 }]} /></View>
    <Text style={s.sectionLabel}>INGREDIENTS</Text>
    <View style={s.optionRow}><TextInput value={ingredient.name} onChangeText={(name) => setIngredient((current) => ({ ...current, name }))} placeholder="Ingredient" placeholderTextColor={C.muted} style={[s.setupInput, { flex: 2 }]} /><TextInput value={ingredient.qty} onChangeText={(qty) => setIngredient((current) => ({ ...current, qty }))} placeholder="Qty" keyboardType="decimal-pad" placeholderTextColor={C.muted} style={[s.setupInput, { flex: 0.7 }]} /><TextInput value={ingredient.unit} onChangeText={(unit) => setIngredient((current) => ({ ...current, unit }))} placeholder="Unit" placeholderTextColor={C.muted} style={[s.setupInput, { flex: 1 }]} /></View>
    <TouchableOpacity onPress={addIngredient} style={s.inlineAdd}><Text style={s.inlineAddText}>Add ingredient</Text></TouchableOpacity>
    {!!draft.ingredients.length && <View style={[s.card, { marginTop: 14 }]}>{draft.ingredients.map((item, index) => <View key={`${item[0]}-${index}`} style={s.itemRow}><Text style={[s.rowTitle, { flex: 1 }]}>{item[1]} {item[2]} {item[0]}</Text><TouchableOpacity onPress={() => setDraft((current) => ({ ...current, ingredients: current.ingredients.filter((_, i) => i !== index) }))}><Ionicons name="close-circle-outline" size={20} color={C.muted} /></TouchableOpacity></View>)}</View>}
    <TextInput value={draft.method} onChangeText={(method) => setDraft((current) => ({ ...current, method }))} placeholder="Cooking method (optional)" multiline placeholderTextColor={C.muted} style={[s.setupInput, { minHeight: 96, paddingTop: 14 }]} />
    <Button text={editing ? "Save recipe" : "Add recipe"} icon="checkmark" disabled={!draft.name.trim() || !draft.ingredients.length} onPress={save} />
  </>;
}

function HouseholdEditor({ household, setHousehold, back }) {
  const [selectedId, setSelectedId] = useState(household.members[0]?.id);
  const member = household.members.find((item) => item.id === selectedId);
  const update = (key, value) =>
    setHousehold((current) => ({
      ...current,
      members: current.members.map((item) =>
        item.id === selectedId ? { ...item, [key]: value } : item,
      ),
    }));
  return (
    <>
      <Back onPress={back} />
      <Header
        overline="MY HOUSEHOLD"
        title="Family profiles"
        sub="Make a quick change whenever real life changes. Your meal plans and saved preferences stay exactly where they are."
      />
      <View style={s.card}>
        {household.members.map((item) => (
          <TouchableOpacity
            key={item.id}
            onPress={() => setSelectedId(item.id)}
            style={[s.itemRow, selectedId === item.id && s.mealChoiceOn]}
          >
            <View style={s.avatar}>
              <Text style={s.avatarText}>{item.name[0]}</Text>
            </View>
            <View style={{ flex: 1 }}>
              <Text style={s.rowTitle}>{item.name}</Text>
              <Text style={s.rowDetail}>
                {item.role} · age {item.age || "not set"}
              </Text>
            </View>
            <Ionicons name="chevron-forward" size={18} color={C.muted} />
          </TouchableOpacity>
        ))}
      </View>
      {member && (
        <View style={s.setupPanel}>
          <Text style={s.sectionLabel}>EDIT {member.name.toUpperCase()}</Text>
          <TextInput
            value={member.name}
            onChangeText={(value) => update("name", value)}
            style={s.setupInput}
            placeholder="Name"
          />
          <TextInput
            value={String(member.age || "")}
            onChangeText={(value) => update("age", value)}
            keyboardType="number-pad"
            style={s.setupInput}
            placeholder="Age"
          />
          <TextInput
            value={String(member.portion || "")}
            onChangeText={(value) => update("portion", Number(value) || 0)}
            keyboardType="decimal-pad"
            style={s.setupInput}
            placeholder="Portion size"
          />
          <TextInput
            value={member.dislikes || ""}
            onChangeText={(value) => update("dislikes", value)}
            style={s.setupInput}
            placeholder="Foods they don't like"
          />
          <TextInput
            value={member.allergies === "None" ? "" : member.allergies}
            onChangeText={(value) => update("allergies", value || "None")}
            style={s.setupInput}
            placeholder="Allergies"
          />
          <TextInput
            value={member.intolerances || ""}
            onChangeText={(value) => update("intolerances", value)}
            style={s.setupInput}
            placeholder="Intolerances"
          />
          <Button
            text="Changes saved"
            icon="checkmark-circle-outline"
            pale
            onPress={back}
          />
        </View>
      )}
    </>
  );
}

function Sub({
  page,
  navigate,
  back,
  next,
  chooseMeal,
  pendingMeal,
  setPendingMeal,
  openMealAudience,
  pendingDiners,
  setPendingDiners,
  pendingSwap,
  setPendingSwap,
  pendingConsumable,
  setPendingConsumable,
  openConsumableAudience,
  addConsumable,
  clearDay,
  mealAssignments,
  attendanceOverrides,
  setAttendanceOverrides,
  planWeek,
  applyMealSelection,
  shopDay,
  setShopDay,
  basket,
  checkoutShop,
  setCheckoutShop,
  delivery,
  setDelivery,
  setArrivalLogged,
  dates,
  setDates,
  addNonFood,
  itemHistory,
  household,
  setHousehold,
  brandRules,
  setBrandRules,
  customRecipes,
  setCustomRecipes,
}) {
  if (page === "SwapConfirm" && pendingSwap)
    return (
      <SwapConfirm
        oldMeal={pendingSwap.oldMeal}
        newMeal={pendingSwap.meal}
        back={() => {
          setPendingSwap(null);
          back();
        }}
        confirm={() => {
          chooseMeal(
            pendingSwap.day,
            pendingSwap.meal,
            pendingSwap.memberIds,
            pendingSwap.oldMeal,
          );
          setPendingSwap(null);
        }}
      />
    );
  if (page.startsWith("DayGroup:")) {
    const day = page.split(":")[1];
    return (
      <DinerPicker
        day={day}
        household={household}
        back={back}
        clear={() => clearDay(day)}
        done={(memberIds) => {
          setPendingDiners({ day, memberIds });
          navigate(`Choose:${day}`);
        }}
      />
    );
  }
  if (page.startsWith("Consumable:") && pendingConsumable) {
    const [, category, name] = page.split(":");
    const existing = (pendingConsumable.items || []).find(
      (item) => item.name === name,
    );
    return (
      <ConsumableAudience
        category={category}
        name={name}
        household={household}
        existingMemberIds={existing?.memberIds || []}
        back={() => {
          setPendingConsumable(null);
          back();
        }}
        done={(memberIds) => {
          addConsumable(category, name, memberIds);
          setPendingConsumable(null);
          back();
        }}
      />
    );
  }
  if (page === "Household")
    return (
      <HouseholdEditor
        household={household}
        setHousehold={setHousehold}
        back={back}
      />
    );
  if (page === "Recipes")
    return (
      <RecipeLibrary
        recipes={customRecipes}
        setRecipes={setCustomRecipes}
        back={back}
      />
    );
  if (page === "MealAudience" && pendingMeal) {
    const { day, meal } = pendingMeal;
    const existing = (mealAssignments[day] || []).find(
      (item) => item.meal === meal,
    );
    return (
      <MealAudience
        day={day}
        meal={meal}
        household={household}
        planWeek={planWeek}
        existingMemberIds={existing?.memberIds || pendingMeal.memberIds || []}
        attendanceOverrides={attendanceOverrides}
        setAttendanceOverrides={setAttendanceOverrides}
        done={(memberIds) => {
          const old = (mealAssignments[day] || []).find(
            (item) =>
              item.meal !== meal &&
              item.memberIds.some((id) => memberIds.includes(id)),
          );
          if (old) {
            setPendingSwap({ day, meal, memberIds, oldMeal: old.meal });
            navigate("SwapConfirm");
          } else {
            chooseMeal(day, meal, memberIds);
            setPendingMeal(null);
          }
        }}
        back={() => {
          setPendingMeal(null);
          back();
        }}
      />
    );
  }
  if (page.startsWith("Choose:")) {
    const day = page.split(":")[1];
    return (
      <>
        <Back onPress={back} />
        <Header
          overline="CHOOSE DINNER"
          title={day}
          sub="Selecting a meal updates your shopping list immediately."
        />
        <View style={s.card}>
          {Object.entries(MEALS).map(([name, meal]) => (
            <TouchableOpacity
              key={name}
              style={[s.mealChoice, next[day] === name && s.mealChoiceOn]}
              onPress={() => {
                const memberIds = household.members.map((member) => member.id);
                const old = (mealAssignments[day] || []).find(
                  (item) => item.meal !== name,
                );
                if (old) {
                  setPendingSwap({
                    day,
                    meal: name,
                    memberIds,
                    oldMeal: old.meal,
                  });
                  navigate("SwapConfirm");
                } else chooseMeal(day, name, memberIds);
              }}
            >
              <View style={s.iconBox}>
                <Ionicons name="restaurant-outline" size={19} color={C.green} />
              </View>
              <View style={{ flex: 1 }}>
                <Text style={s.rowTitle}>{name}</Text>
                <Text style={s.rowDetail}>
                  {meal.time} minutes · {meal.ingredients.length} ingredients
                </Text>
              </View>
              {next[day] === name && (
                <Ionicons name="checkmark-circle" size={21} color={C.green} />
              )}
            </TouchableOpacity>
          ))}
        </View>
        <TouchableOpacity
          onPress={() => navigate(`DayGroup:${day}`)}
          style={s.setupBack}
        >
          <Text style={s.link}>
            Need different meals for adults and children?
          </Text>
        </TouchableOpacity>
      </>
    );
  }
  if (page === "Compare")
    return (
      <Compare
        back={back}
        basket={basket}
        checkoutShop={checkoutShop}
        setCheckoutShop={setCheckoutShop}
        delivery={delivery}
        setDelivery={setDelivery}
      />
    );
  if (page === "MealLibrary")
    return (
      <MealLibrary
        back={back}
        currentPlan={next}
        apply={applyMealSelection}
        household={household}
        customRecipes={customRecipes}
      />
    );
  if (page === "Brands")
    return (
      <BrandPreferences
        back={back}
        rules={brandRules}
        setRules={setBrandRules}
      />
    );
  if (page === "Dates")
    return (
      <Dates
        back={back}
        dates={dates}
        setDates={setDates}
        done={() => {
          setArrivalLogged(true);
          back();
        }}
      />
    );
  if (page === "NonFood")
    return (
      <NonFood back={back} addNonFood={addNonFood} itemHistory={itemHistory} />
    );
  if (page === "ShopDay")
    return (
      <>
        <Back onPress={back} />
        <Header
          overline="SHOP ROUTINE"
          title="Weekly shop day"
          sub="We will prompt you to plan the upcoming week before this day."
        />
        <View style={s.card}>
          {DAYS.map((day) => (
            <TouchableOpacity
              key={day}
              style={s.itemRow}
              onPress={() => {
                setShopDay(day);
                back();
              }}
            >
              <Text style={[s.rowTitle, { flex: 1 }]}>{day}</Text>
              {shopDay === day && (
                <Ionicons name="checkmark-circle" size={21} color={C.green} />
              )}
            </TouchableOpacity>
          ))}
        </View>
      </>
    );
  return null;
}

function MealLibrary({ back, currentPlan, apply, household, customRecipes = {} }) {
  const [selected, setSelected] = useState(() =>
    Object.values(currentPlan || {}).filter(Boolean),
  );
  const totalPortions = household.members.reduce(
    (sum, member) => sum + Number(member.portion || 0),
    0,
  );
  const toggle = (meal) =>
    setSelected((items) =>
      items.includes(meal)
        ? items.filter((item) => item !== meal)
        : items.length < 7
          ? [...items, meal]
          : items,
    );
  return (
    <>
      <Back onPress={back} />
      <Header
        overline="OUR FAMILY MEALS"
        title="What do we fancy this week?"
        sub="Choose the dinners. Ingredients are added automatically."
      />
      <View style={s.familyContext}>
        <Ionicons name="people-outline" size={19} color={C.green} />
        <Text style={s.familyContextText}>
          Planning for {household.members.length} people · {totalPortions} adult
          portions per shared meal
        </Text>
      </View>
      <View style={s.progress}>
        <View style={s.progressTop}>
          <Text style={s.progressTitle}>Selected meals</Text>
          <Text style={s.progressCount}>{selected.length} of 7</Text>
        </View>
        <View style={s.track}>
          <View
            style={[s.trackFill, { width: selected.length * (100 / 7) + "%" }]}
          />
        </View>
      </View>
      <View style={s.card}>
        {Object.entries({ ...MEALS, ...customRecipes }).map(([name, meal]) => {
          const on = selected.includes(name);
          const alreadyUsed = Object.values(currentPlan).includes(name);
          return (
            <TouchableOpacity
              key={name}
              style={[s.savedMealRow, on && s.mealChoiceOn]}
              onPress={() => toggle(name)}
            >
              <View style={[s.mealThumb, on && s.mealThumbOn]}>
                <Ionicons
                  name={on ? "checkmark" : "restaurant-outline"}
                  size={20}
                  color={on ? C.white : C.green}
                />
              </View>
              <View style={{ flex: 1 }}>
                <Text style={s.savedMealName}>{name}</Text>
                <Text style={s.rowDetail}>
                  {meal.time} min · {meal.ingredients.length} ingredients ·
                  family recipe
                </Text>
                {alreadyUsed && (
                  <Text style={s.familyFavourite}>REGULAR FAMILY MEAL</Text>
                )}
              </View>
              <Ionicons
                name={on ? "checkbox" : "square-outline"}
                size={24}
                color={on ? C.green : C.muted}
              />
            </TouchableOpacity>
          );
        })}
      </View>
      <Button
        text={
          selected.length
            ? "Add " + selected.length + " meals to this week"
            : "Select meals to continue"
        }
        icon="calendar-outline"
        disabled={!selected.length}
        onPress={() => apply(selected)}
      />
    </>
  );
}

function BrandPreferences({ back, rules, setRules }) {
  const toggle = (brand, product) =>
    setRules((current) => ({
      ...current,
      [brand]: (current[brand] || []).includes(product)
        ? current[brand].filter((item) => item !== product)
        : [...(current[brand] || []), product],
    }));
  return (
    <>
      <Back onPress={back} />
      <Header
        overline="PROTECTED CHOICES"
        title="Brands that matter"
        sub="Lock the products your household will not swap. Comparisons must use that exact brand or ask permission."
      />
      {Object.entries(BRAND_CATALOGUE).map(([brand, products]) => (
        <View key={brand} style={s.brandSection}>
          <View style={s.brandHeading}>
            <View style={s.brandBadge}>
              <Text style={s.brandBadgeText}>{brand.toUpperCase()}</Text>
            </View>
            <View style={{ flex: 1 }}>
              <Text style={s.rowTitle}>{brand}</Text>
              <Text style={s.rowDetail}>
                {(rules[brand] || []).length} protected products
              </Text>
            </View>
          </View>
          <View style={s.choiceWrap}>
            {products.map((product) => {
              const locked = (rules[brand] || []).includes(product);
              return (
                <TouchableOpacity
                  key={product}
                  onPress={() => toggle(brand, product)}
                  style={[s.productChoice, locked && s.productChoiceOn]}
                >
                  <Ionicons
                    name={locked ? "lock-closed" : "add"}
                    size={16}
                    color={locked ? C.white : C.green}
                  />
                  <Text
                    style={[s.productChoiceText, locked && { color: C.white }]}
                  >
                    {product}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </View>
        </View>
      ))}
      <View style={s.info}>
        <Ionicons name="shield-checkmark-outline" size={19} color={C.green} />
        <Text style={s.infoText}>
          Protected products will never be replaced silently by an own-brand or
          equivalent product.
        </Text>
      </View>
    </>
  );
}

function NonFood({ back, addNonFood, itemHistory }) {
  const [query, setQuery] = useState("");
  const options = [
    "Toilet roll",
    "Toothpaste",
    "Kitchen roll",
    "Bin bags",
    "AA batteries",
    "Candles",
    "Shampoo",
    "Hand soap",
    "Laundry detergent",
    "Dishwasher tablets",
    "Cleaning spray",
    "Kitchen foil",
    "Pet food",
  ].filter((x) => x.toLowerCase().includes(query.toLowerCase()));
  return (
    <>
      <Back onPress={back} />
      <Header
        overline="NON-FOOD ITEMS"
        title="Add household essentials"
        sub="Search for anything you need. Reorder patterns are learned privately for future reminders."
      />
      <View style={s.addBar}>
        <Ionicons name="search" size={19} color={C.muted} />
        <TextInput
          autoFocus
          value={query}
          onChangeText={setQuery}
          placeholder="Search household items"
          placeholderTextColor={C.muted}
          style={s.input}
        />
      </View>
      <View style={s.card}>
        {options.map((name) => (
          <View key={name} style={s.itemRow}>
            <View style={s.iconBox}>
              <Ionicons name="cube-outline" size={18} color={C.green} />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={s.rowTitle}>{name}</Text>
              <Text style={s.rowDetail}>
                {itemHistory[name]
                  ? `Ordered ${itemHistory[name].orders} times · roughly every ${itemHistory[name].every} weeks`
                  : "No order history yet"}
              </Text>
            </View>
            <TouchableOpacity
              style={s.inlineAdd}
              onPress={() => addNonFood(name)}
            >
              <Text style={s.inlineAddText}>Add</Text>
            </TouchableOpacity>
          </View>
        ))}
      </View>
      {query && !options.length && (
        <Button
          text={`Add “${query}”`}
          icon="add"
          onPress={() => {
            addNonFood(query);
            back();
          }}
        />
      )}
    </>
  );
}
function Compare({
  back,
  basket,
  checkoutShop,
  setCheckoutShop,
  delivery,
  setDelivery,
}) {
  const [chosen, setChosen] = useState(checkoutShop),
    [stage, setStage] = useState(checkoutShop ? "returned" : "choose"),
    [timing, setTiming] = useState(delivery);
  const retailerLinks = {
    Tesco: "https://www.tesco.com/groceries/en-GB/",
    Morrisons: "https://groceries.morrisons.com/",
    "Sainsbury's": "https://www.sainsburys.co.uk/gol-ui/groceries",
  };
  const sendBasket = async () => {
    setStage("sent");
    try {
      await Linking.openURL(retailerLinks[chosen]);
    } catch (e) {
      /* Snack preview may block external tabs. */
    }
  };
  return (
    <>
      <Back onPress={back} />
      <Header
        overline="FULL BASKET COMPARISON"
        title="Choose a supermarket"
        sub={`${basket.length} products compared. Demo prices shown.`}
      />
      {shops.map(([name, total], i) => (
        <TouchableOpacity
          key={name}
          style={[s.shop, i === 0 && s.best, chosen === name && s.selected]}
          onPress={() => {
            setChosen(name);
            setStage("choose");
          }}
        >
          <View style={s.shopTop}>
            <View>
              <Text style={s.shopName}>{name}</Text>
              <Text style={s.rowDetail}>
                {basket.length}/{basket.length} products matched
              </Text>
            </View>
            {i === 0 && <Text style={s.bestTag}>BEST VALUE</Text>}
          </View>
          <Text style={s.shopTotal}>{money(total)}</Text>
          <Text style={s.shopSaving}>Estimated basket total</Text>
          {chosen === name && (
            <View style={s.permission}>
              <Ionicons
                name="shield-checkmark-outline"
                size={18}
                color={C.green}
              />
              <Text style={s.permissionText}>
                Allow Our Weekly Shop to add these {basket.length} products to
                your {name} basket. We cannot place the order or take payment.
              </Text>
            </View>
          )}
        </TouchableOpacity>
      ))}
      {chosen && stage === "choose" && (
        <>
          <Button
            text={`Send this to my ${chosen} basket`}
            icon="open-outline"
            onPress={sendBasket}
          />
          <Text style={s.checkoutNote}>
            You will sign in securely with {chosen}. Your basket transfers there
            and checkout stays entirely on the supermarket website.
          </Text>
        </>
      )}
      {chosen && stage === "sent" && (
        <View style={s.returnCard}>
          <Ionicons name="open-outline" size={22} color={C.green} />
          <Text style={s.returnTitle}>Complete checkout with {chosen}</Text>
          <Text style={s.returnText}>
            Sign in, review substitutions and pay on the {chosen} website. Then
            return here when your order is confirmed.
          </Text>
          <Button
            text="I’ve checked out — continue"
            icon="checkmark"
            onPress={() => setStage("returned")}
          />
          <TouchableOpacity onPress={sendBasket}>
            <Text style={[s.link, { textAlign: "center", marginTop: 13 }]}>
              Open {chosen} again
            </Text>
          </TouchableOpacity>
        </View>
      )}
      {chosen && stage === "returned" && (
        <ArrivalPicker value={timing} onChange={setTiming} retailer={chosen} />
      )}
      {chosen && stage === "returned" && (
        <Button
          text="Save arrival time"
          icon="calendar-outline"
          onPress={() => {
            setCheckoutShop(chosen);
            setDelivery(timing);
            back();
          }}
          disabled={!timing}
        />
      )}
    </>
  );
}

function ArrivalPicker({ value, onChange, retailer }) {
  const [month, setMonth] = useState(8),
    [selectedDay, setSelectedDay] = useState(
      value ? Number(value.split("-")[2]?.slice(0, 2)) : 12,
    ),
    [hour, setHour] = useState("10"),
    [minute, setMinute] = useState("00");
  const monthNames = ["September", "October", "November"];
  const days = Array.from({ length: 30 }, (_, i) => i + 1);
  const save = (day = selectedDay, hourValue = hour, minuteValue = minute) => {
    setSelectedDay(day);
    setHour(hourValue);
    setMinute(minuteValue);
    onChange(`${monthNames[month - 8]} ${day}, ${hourValue}:${minuteValue}`);
  };
  return (
    <>
      <Text style={s.sectionLabel}>WHEN WILL YOUR SHOP ARRIVE?</Text>
      <Text style={s.deliveryHelp}>
        Choose the delivery or collection date and time confirmed by {retailer}.
      </Text>
      <View style={s.pickerCard}>
        <View style={s.monthRow}>
          <TouchableOpacity
            disabled={month === 8}
            onPress={() => setMonth((m) => m - 1)}
          >
            <Ionicons
              name="chevron-back"
              size={20}
              color={month === 8 ? C.line : C.green}
            />
          </TouchableOpacity>
          <Text style={s.monthTitle}>{monthNames[month - 8]} 2026</Text>
          <TouchableOpacity
            disabled={month === 10}
            onPress={() => setMonth((m) => m + 1)}
          >
            <Ionicons
              name="chevron-forward"
              size={20}
              color={month === 10 ? C.line : C.green}
            />
          </TouchableOpacity>
        </View>
        <View style={s.weekLabels}>
          {["M", "T", "W", "T", "F", "S", "S"].map((d, i) => (
            <Text key={`${d}${i}`} style={s.weekLabel}>
              {d}
            </Text>
          ))}
        </View>
        <View style={s.calendarGrid}>
          {days.map((day) => (
            <TouchableOpacity
              key={day}
              style={[s.calendarDay, selectedDay === day && s.calendarDayOn]}
              onPress={() => save(day)}
            >
              <Text
                style={[
                  s.calendarDayText,
                  selectedDay === day && { color: C.white },
                ]}
              >
                {day}
              </Text>
            </TouchableOpacity>
          ))}
        </View>
        <Text style={s.timeLabel}>TIME</Text>
        <View style={s.timeRow}>
          <View style={s.timeGroup}>
            <Text style={s.timeCaption}>Hour</Text>
            <View style={s.timeChoices}>
              {["08", "10", "12", "14", "16", "18", "20"].map((h) => (
                <TouchableOpacity
                  key={h}
                  style={[s.timeChoice, hour === h && s.timeChoiceOn]}
                  onPress={() => save(selectedDay, h, minute)}
                >
                  <Text
                    style={[s.timeChoiceText, hour === h && { color: C.white }]}
                  >
                    {h}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>
          </View>
          <View style={s.timeGroup}>
            <Text style={s.timeCaption}>Minutes</Text>
            <View style={s.timeChoices}>
              {["00", "15", "30", "45"].map((m) => (
                <TouchableOpacity
                  key={m}
                  style={[s.timeChoice, minute === m && s.timeChoiceOn]}
                  onPress={() => save(selectedDay, hour, m)}
                >
                  <Text
                    style={[
                      s.timeChoiceText,
                      minute === m && { color: C.white },
                    ]}
                  >
                    {m}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>
          </View>
        </View>
        {value && (
          <View style={s.pickerResult}>
            <Ionicons name="calendar-outline" size={17} color={C.green} />
            <Text style={s.pickerResultText}>{value}</Text>
          </View>
        )}
      </View>
    </>
  );
}
function Dates({ back, dates, setDates, done }) {
  return (
    <>
      <Back onPress={back} />
      <Header
        overline="PUTTING YOUR SHOP AWAY"
        title="Log use-by dates"
        sub="Only short-life products are shown. This takes under a minute and allows the app to protect food from waste."
      />
      <View style={s.card}>
        {Object.entries(dates).map(([name, date]) => (
          <View key={name} style={s.dateInputRow}>
            <View style={{ flex: 1 }}>
              <Text style={s.rowTitle}>{name}</Text>
              <Text style={s.rowDetail}>Use by date</Text>
            </View>
            <TextInput
              value={date}
              onChangeText={(value) =>
                setDates((p) => ({ ...p, [name]: value }))
              }
              style={s.dateInput}
            />
          </View>
        ))}
      </View>
      <View style={s.info}>
        <Ionicons name="sparkles-outline" size={19} color={C.green} />
        <Text style={s.infoText}>
          Once saved, meal order is checked automatically and earlier meal
          suggestions appear when needed.
        </Text>
      </View>
      <Button text="Save dates and assess meal plan" onPress={done} />
    </>
  );
}

function Header({ overline, title, sub }) {
  return (
    <View style={s.header}>
      <Text style={s.overline}>{overline}</Text>
      <Text style={s.title}>{title}</Text>
      <Text style={s.subtitle}>{sub}</Text>
    </View>
  );
}
function Back({ onPress }) {
  return (
    <TouchableOpacity style={s.back} onPress={onPress}>
      <Ionicons name="arrow-back" size={19} color={C.green} />
      <Text style={s.link}>Back</Text>
    </TouchableOpacity>
  );
}
function Button({ text, onPress, icon, pale, disabled }) {
  return (
    <TouchableOpacity
      disabled={disabled}
      onPress={onPress}
      style={[s.button, pale && s.buttonPale, disabled && { opacity: 0.4 }]}
    >
      {icon && (
        <Ionicons name={icon} size={18} color={pale ? C.green : C.white} />
      )}
      <Text style={[s.buttonText, pale && { color: C.green }]}>{text}</Text>
    </TouchableOpacity>
  );
}
function SmallButton({ icon, text, onPress, pale }) {
  return (
    <TouchableOpacity
      onPress={onPress}
      style={[s.smallButton, pale && s.smallPale]}
    >
      <Ionicons name={icon} size={15} color={pale ? C.green : C.white} />
      <Text style={[s.smallText, pale && { color: C.green }]}>{text}</Text>
    </TouchableOpacity>
  );
}
function Nav({ tab, setTab }) {
  const tabs = [
    ["This Week", "calendar-outline", "calendar"],
    ["Plan Shop", "create-outline", "create"],
    ["Basket", "basket-outline", "basket"],
    ["At Home", "cube-outline", "cube"],
    ["Account", "person-outline", "person"],
  ];
  return (
    <View style={s.nav}>
      {tabs.map(([name, off, on]) => (
        <TouchableOpacity
          key={name}
          style={s.navItem}
          onPress={() => setTab(name)}
        >
          <Ionicons
            name={tab === name ? on : off}
            size={20}
            color={tab === name ? C.green : C.muted}
          />
          <Text style={[s.navText, tab === name && s.navTextOn]}>{name}</Text>
        </TouchableOpacity>
      ))}
    </View>
  );
}
function niceDate(date) {
  if (!date) return "No date";
  return new Date(`${date}T12:00:00`).toLocaleDateString("en-GB", {
    day: "numeric",
    month: "short",
  });
}

export default function DeliverySplash({ onFinish }) {
  const vanX = useRef(new Animated.Value(-520)).current;
  const openOpacity = useRef(new Animated.Value(0)).current;
  const logoX = useRef(new Animated.Value(-108)).current;
  const logoY = useRef(new Animated.Value(2)).current;
  const logoScale = useRef(new Animated.Value(0.13)).current;
  const logoOpacity = useRef(new Animated.Value(0)).current;
  const tagOpacity = useRef(new Animated.Value(0)).current;
  const screenOpacity = useRef(new Animated.Value(1)).current;
  const closedOpacity = openOpacity.interpolate({
    inputRange: [0, 0.94, 1],
    outputRange: [1, 1, 0],
  });

  useEffect(() => {
    Animated.sequence([
      Animated.timing(vanX, {
        toValue: 0,
        duration: 820,
        easing: Easing.out(Easing.cubic),
        useNativeDriver: true,
      }),
      Animated.delay(130),
      Animated.timing(openOpacity, {
        toValue: 1,
        duration: 170,
        easing: Easing.inOut(Easing.quad),
        useNativeDriver: true,
      }),
      Animated.delay(80),
      Animated.timing(logoOpacity, {
        toValue: 1,
        duration: 70,
        useNativeDriver: true,
      }),
      Animated.parallel([
        Animated.timing(logoX, {
          toValue: 0,
          duration: 720,
          easing: Easing.out(Easing.cubic),
          useNativeDriver: true,
        }),
        Animated.timing(logoY, {
          toValue: 0,
          duration: 720,
          easing: Easing.out(Easing.cubic),
          useNativeDriver: true,
        }),
        Animated.timing(logoScale, {
          toValue: 1,
          duration: 720,
          easing: Easing.out(Easing.back(1.03)),
          useNativeDriver: true,
        }),
      ]),
      Animated.delay(100),
      Animated.parallel([
        Animated.timing(vanX, {
          toValue: 520,
          duration: 650,
          easing: Easing.in(Easing.cubic),
          useNativeDriver: true,
        }),
        Animated.timing(tagOpacity, {
          toValue: 1,
          duration: 300,
          delay: 260,
          useNativeDriver: true,
        }),
      ]),
      Animated.delay(330),
      Animated.timing(screenOpacity, {
        toValue: 0,
        duration: 230,
        useNativeDriver: true,
      }),
    ]).start(({ finished }) => {
      if (finished && onFinish) onFinish();
    });
  }, [onFinish]);

  return (
    <Animated.View style={[styles.splash, { opacity: screenOpacity }]}>
      <View style={styles.splashStage}>
        <Animated.View style={[styles.vanImageWrap, { opacity: closedOpacity, transform: [{ translateX: vanX }] }]}>
          <Image source={{ uri: LOCKED_CLOSED_VAN_IMAGE }} style={styles.vanImage} />
        </Animated.View>
        <Animated.View style={[styles.vanImageWrap, { opacity: openOpacity, transform: [{ translateX: vanX }] }]}>
          <Image source={{ uri: LOCKED_OPEN_VAN_IMAGE }} style={styles.vanImage} />
        </Animated.View>
        <Animated.View style={[styles.splashLogo, { opacity: logoOpacity, transform: [{ translateX: logoX }, { translateY: logoY }, { scale: logoScale }] }]}>
          <Image source={{ uri: LOGO_IMAGE }} style={styles.splashLogoImage} />
        </Animated.View>
      </View>
      <Animated.View style={{ opacity: tagOpacity, alignItems: "center" }}>
        <Text style={styles.splashTitle}>Our Weekly Shop</Text>
        <Text style={styles.splashTag}>Your weekly shop, at the best price.</Text>
      </Animated.View>
    </Animated.View>
  );
}

